구체 산술 타입 complex (원문 코드 발췌)
class complex {
    double re, im; // 메모리 표현: double 두 개
public:
    complex(double r, double i) :re{r}, im{i} {} // 두 스칼라를 이용해 complex 생성
    complex(double r) :re{r}, im{0} {} // 스칼라 하나를 이용해 complex 생성
    complex() :re{0}, im{0} {} // 기본 complex: {0,0}

    double real() const { return re; }
    void real(double d) { re=d; }
    double imag() const { return im; }
    void imag(double d) { im=d; }

    complex& operator+=(complex z)
    {
        re+=z.re; // re와 im에 더하기
        im+=z.im;
        return *this; // 결과 반환
    }
    complex& operator-=(complex z)
    {
        re-=z.re;
        im-=z.im;
        return *this;
    }

    complex& operator*=(complex); // 클래스 밖의 어딘가에서 정의
    complex& operator/=(complex); // 클래스 밖의 어딘가에서 정의
};

